('371650a9-781e-5595-ba2f-1d9c7a33ba11'::uuid,'est2','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"[Table: CP-c25-15 — Data set A: Value/Frequency 10 → 2, 11 → 3, 12 → 7, 13 → 3, 14 → 9, 15 → 5. Data set B: 13 → 2, 14 → 3, 15 → 7, 16 → 3, 17 → 9, 18 → 5]\nThe tables show the frequencies of the values for data sets A and B. Which of the following statements best compares the means and the standard deviations of data sets A and B?"'::jsonb,'[{"key":"A","text":"The mean of data set B is equal to the mean of data set A, and the standard deviation of data set B is equal to the standard deviation of data set A."},{"key":"B","text":"The mean of data set B is equal to the mean of data set A, and the standard deviation of data set B is greater than the standard deviation of data set A."},{"key":"C","text":"The mean of data set B is greater than the mean of data set A, and the standard deviation of data set B is equal to the standard deviation of data set A."},{"key":"D","text":"The mean of data set B is greater than the mean of data set A, and the standard deviation of data set B is greater than the standard deviation of data set A."}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"panda.md","source_sha256":"e120378a8127836a41962876a763889bbb1df92d70c90242206130acfa43e008","source_question_id":"CP-c25-15","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/CP-c25-15.png","image_alt":"Original graph, diagram, or table for CP-c25-15","visual_verified":true}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from panda.md (CP-c25-15)."'::jsonb),
