('4c6cb736-fac3-5f34-98b4-a210121d4975'::uuid,'est2','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"To evaluate the water quality of lakes A and B, researchers took 81 samples of water from each lake. The mean pH of the samples from lake A is 7.3, and the mean pH of the samples from lake B is 6.8. Which of the following must be true?\n\nI. The median pH of the samples from lake A is greater than the median pH of the samples from lake B.\nII. The highest pH measured among the samples from lake A is greater than the highest pH measured among the samples from lake B."'::jsonb,'[{"key":"A","text":"I only"},{"key":"B","text":"II only"},{"key":"C","text":"I and II"},{"key":"D","text":"Neither I nor II"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"panda.md","source_sha256":"e120378a8127836a41962876a763889bbb1df92d70c90242206130acfa43e008","source_question_id":"CP-c25-23","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from panda.md (CP-c25-23)."'::jsonb),
