('78f72dfb-c7c8-5b38-a568-2dc21cd47643'::uuid,'est2','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"[Figure: CP-c25-27 — dot plot of data set A over values 18–23]\nThe dot plot shows the distribution of values in data set A. Data set B is created by multiplying each value in data set A by 2. Which of the following statements about the medians and the ranges of data sets A and B must be true?"'::jsonb,'[{"key":"A","text":"The median of data set B is equal to the median of data set A, and the range of data set B is equal to the range of data set A."},{"key":"B","text":"The median of data set B is twice the median of data set A, and the range of data set B is equal to the range of data set A."},{"key":"C","text":"The median of data set B is equal to the median of data set A, and the range of data set B is twice the range of data set A."},{"key":"D","text":"The median of data set B is twice the median of data set A, and the range of data set B is twice the range of data set A."}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"panda.md","source_sha256":"e120378a8127836a41962876a763889bbb1df92d70c90242206130acfa43e008","source_question_id":"CP-c25-27","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/CP-c25-27.png","image_alt":"Original graph, diagram, or table for CP-c25-27","visual_verified":true}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from panda.md (CP-c25-27)."'::jsonb),
