('baa1c77c-f8fa-5a31-98fd-72fa18e289ff'::uuid,'est2','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"The daily totals of enrollments at Sunnyside Summer Camp last Monday through Saturday were 17, 19, 23, 14, 25, and 28. What was the average number of enrollments per day?"'::jsonb,'[{"key":"A","text":"126"},{"key":"B","text":"28"},{"key":"C","text":"21"},{"key":"D","text":"18"},{"key":"E","text":"14"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"pt2.md","source_sha256":"dc3f96cb13caae485d8f8df3913a14000c0cee73962cf2be70e8202d99a231b9","source_question_id":"P2-05","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from pt2.md (P2-05)."'::jsonb),
